function LLMLogo({ provider, className }: LogoProps & { provider: string }) {
  switch (provider) {
    case "deepseek":
      return <DeepSeekLogo className={className} />
    case "openai":
      return <OpenAILogo className={className} />
    case "gemini":
      return <GeminiLogo className={className} />
    case "groq":
      return <GroqLogo className={className} />
    default:
      return null
  }
}

export { DeepSeekLogo, GeminiLogo, LLMLogo, OpenAILogo }
